export function Control({
  highlight = "{{highlight}}",
  label = "{{label}}",
  accent = "{{accent}}",
}) {
  const box = (key) => ({ padding: 8, borderRadius: 8, border: highlight === key ? "2px solid #241430" : "2px solid transparent", background: highlight === key ? "#24143008" : "transparent" });
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 16, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 12, color: "#241430aa", display: "flex", flexDirection: "column", gap: 10 }}>
      <div style={box("button")}><button type="button" style={{ fontWeight: 600, fontSize: 13, padding: "7px 14px", borderRadius: 7, border: "none", background: accent, color: "#241430", cursor: "pointer" }}>{label}</button></div>
      <div style={box("checkbox")}><label><input type="checkbox" checked readOnly disabled /> Agree</label></div>
      <div style={box("slider")}><input type="range" min="0" max="10" defaultValue={6} disabled style={{ accentColor: accent }} /></div>
      <p style={{ margin: 0 }}>A control lets someone perform an action or change a value &mdash; the highlighted one is annotated below</p>
    </div>
  );
}
